#include <cstddef>
#include <cstdint>

struct WorldOptions
{
    uint32_t size;
    int32_t  width;
    int32_t  height;
    int32_t  gravity;
    uint32_t seed;
};

struct Settings { int32_t width; int32_t height; int32_t gravity; uint32_t seed; };

#define HAS_MEMBER(p, member) ((p)->size >= offsetof(WorldOptions, member) + sizeof((p)->member))

int32_t readOptions(const WorldOptions* options, Settings* out)
{
    if (!options || !out || !HAS_MEMBER(options, height)) return 1;
    Settings s{};
    s.width = options->width;
    s.height = options->height;
    s.gravity = HAS_MEMBER(options, gravity) ? options->gravity : 10;
    s.seed = HAS_MEMBER(options, seed) ? options->seed : 12345u;
    *out = s;
    return 0;
}

uint32_t versionOfSize(uint32_t size)
{
    if (size >= offsetof(WorldOptions, seed) + sizeof(uint32_t)) return 3;
    if (size >= offsetof(WorldOptions, gravity) + sizeof(int32_t)) return 2;
    if (size >= offsetof(WorldOptions, height) + sizeof(int32_t)) return 1;
    return 0;
}

unitTests:
TEST("a version 3 caller") { WorldOptions o{ sizeof(WorldOptions), 64, 32, 7, 99 }; Settings s{}; CHECK_EQ(readOptions(&o, &s), 0); CHECK_EQ(s.width, 64); CHECK_EQ(s.height, 32); CHECK_EQ(s.gravity, 7); CHECK_EQ(s.seed, 99u); }
TEST("a version 1 caller gets defaults") { WorldOptions o{ 12, 64, 32, 7, 99 }; Settings s{}; CHECK_EQ(readOptions(&o, &s), 0); CHECK_EQ(s.gravity, 10); CHECK_EQ(s.seed, 12345u); }
TEST("a version 2 caller") { WorldOptions o{ 16, 8, 8, 3, 99 }; Settings s{}; CHECK_EQ(readOptions(&o, &s), 0); CHECK_EQ(s.gravity, 3); CHECK_EQ(s.seed, 12345u); }
TEST("a newer caller") { WorldOptions o{ 64, 1, 2, 3, 4 }; Settings s{}; CHECK_EQ(readOptions(&o, &s), 0); CHECK_EQ(s.seed, 4u); }
TEST("too small or missing") { WorldOptions o{ 8, 1, 2, 3, 4 }; Settings s{ -1, -1, -1, 1 }; CHECK_EQ(readOptions(&o, &s), 1); CHECK_EQ(s.width, -1); CHECK_EQ(readOptions(nullptr, &s), 1); WorldOptions ok{ sizeof(WorldOptions), 1, 2, 3, 4 }; CHECK_EQ(readOptions(&ok, nullptr), 1); }
TEST("versions from sizes") { CHECK_EQ(versionOfSize(12), 1u); CHECK_EQ(versionOfSize(16), 2u); CHECK_EQ(versionOfSize(20), 3u); CHECK_EQ(versionOfSize(100), 3u); CHECK_EQ(versionOfSize(8), 0u); CHECK_EQ(versionOfSize(0), 0u); }

